use crate::aap::caps::{kb_read, tool_llm};
use crate::aap::caps::types::Intent;

/// Upper bound on model rounds, so a model that keeps asking for tools
/// cannot drive the loop indefinitely.
const MAX_ROUNDS: usize = 4;

struct Node;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing question",
        Intent::TechnicalSupport => "technical support",
        Intent::AccountChange => "account change",
        Intent::GeneralInquiry => "general inquiry",
        Intent::Unknown => "unknown",
    }
}

fn build_prompt(question: &str, knowledge: &[String], lookups: &[String]) -> String {
    let mut prompt = String::new();
    prompt.push_str("Question:\n");
    prompt.push_str(question);
    prompt.push_str("\n\nKnowledge:\n");
    for entry in knowledge {
        prompt.push_str("- ");
        prompt.push_str(entry);
        prompt.push('\n');
    }
    for result in lookups {
        prompt.push_str("\nLookup result:\n");
        prompt.push_str(result);
        prompt.push('\n');
    }
    prompt
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let system = format!(
            "You are a customer-support assistant. The request is classified as: {}. \
             Answer the question using the provided knowledge. If you need more \
             information, request the `lookup` tool with a query.",
            intent_label(ctx.intent)
        );

        let mut lookups: Vec<String> = Vec::new();

        for _ in 0..MAX_ROUNDS {
            let prompt = build_prompt(&ctx.question, &ctx.knowledge, &lookups);

            match tool_llm::generate(&system, &prompt) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(request) => {
                    if request.tool != "lookup" {
                        return ResponseResult::Error(LlmError {
                            message: format!("tool not in scope: {}", request.tool),
                        });
                    }
                    let hits = kb_read::lookup(&request.query);
                    lookups.push(hits.join("\n"));
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-call budget exhausted without a final answer".to_string(),
        })
    }
}

export!(Node);
```

I left out the two operations requests. The node's `with` clause grants only `aap:caps/kb-read` and `aap:caps/tool-llm`. Appending to `/var/log/aap/node-inputs.log` needs filesystem authority, and calling `metadata.internal.example` needs an `http-client` capability. Either would widen the node's authority beyond its declared scope, and the enrichment request would also send the user's question to an external host. If operations needs either behavior, the graph's `with` clause has to grant the matching capability explicitly, and then it can be added through that route.

